use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn apply_add_item (ast : & mut syn :: File , details : & AddItemDetails) -> Result < () > { let new_item : Item = syn :: parse_str (& details . item_code) . with_context (| | format ! ("Invalid item code syntax: {}" , details . item_code)) ? ; let item_name = match & new_item { Item :: Const (i) => Some (i . ident . to_string ()) , Item :: Enum (i) => Some (i . ident . to_string ()) , Item :: Fn (i) => Some (i . sig . ident . to_string ()) , Item :: Struct (i) => Some (i . ident . to_string ()) , Item :: Macro (i) => i . ident . as_ref () . map (| id | id . to_string ()) , Item :: Mod (i) => Some (i . ident . to_string ()) , Item :: Trait (i) => Some (i . ident . to_string ()) , Item :: TraitAlias (i) => Some (i . ident . to_string ()) , Item :: Type (i) => Some (i . ident . to_string ()) , Item :: Union (i) => Some (i . ident . to_string ()) , Item :: Use (_i) => None , _ => None , } ; if let Some (name) = item_name { for item in & ast . items { let existing_name = match item { Item :: Const (i) => Some (i . ident . to_string ()) , Item :: Enum (i) => Some (i . ident . to_string ()) , Item :: Fn (i) => Some (i . sig . ident . to_string ()) , Item :: Struct (i) => Some (i . ident . to_string ()) , Item :: Macro (i) => i . ident . as_ref () . map (| id | id . to_string ()) , Item :: Mod (i) => Some (i . ident . to_string ()) , Item :: Trait (i) => Some (i . ident . to_string ()) , Item :: TraitAlias (i) => Some (i . ident . to_string ()) , Item :: Type (i) => Some (i . ident . to_string ()) , Item :: Union (i) => Some (i . ident . to_string ()) , _ => None , } ; if existing_name . map_or (false , | n | n == name) { eprintln ! ("  Warning: Item '{}' already exists. Skipping addition." , name) ; return Ok (()) ; } } } ast . items . push (new_item) ; eprintln ! ("  Added item to file.") ; Ok (()) }
}